<template><div><section v-if="job&&contest" class="space-y-6"><header><p class="premium-kicker text-xs font-bold uppercase text-brand">Live contest · {{ contest.status }}</p><h1 class="premium-title mt-2 text-3xl font-800">{{ job.title }}</h1><p class="mt-2 text-slate-500">Ends {{ store.date(contest.endTime) }} · Prize {{ store.money(job.budget) }}</p></header><div class="grid gap-6 lg:grid-cols-[1fr_20rem]"><article class="panel p-6"><h2 class="font-800">Live entries</h2><div v-for="(bid,index) in ranked" :key="bid.userId" class="mt-4 flex items-center justify-between rounded-xl border border-slate-100 p-4"><span><b class="mr-3 text-brand">#{{ index+1 }}</b><RouterLink :to="`/profile/${bid.userId}`">{{ store.user(bid.userId)?.name }}</RouterLink></span><span class="flex items-center gap-3"><b>{{ store.money(bid.amount) }}</b><button v-if="owner&&!contest.winnerId" class="btn-brand" @click="award(bid)">Award</button><b v-if="contest.winnerId===bid.userId" class="text-emerald-600"><i class="fa-solid fa-trophy"></i> Winner</b></span></div><form v-if="freelancer&&!ownBid&&contest.status==='ACTIVE'" class="mt-5 flex items-end gap-3" @submit.prevent="enter"><label class="flex-1"><span class="mb-1 block text-xs font-bold">Entry amount</span><input v-model.number="amount" class="field" type="number" min="1" :max="job.budget" required></label><button class="btn-brand">Submit entry</button></form></article><aside class="panel p-5"><h2 class="font-800">Contest status</h2><p class="mt-4 text-3xl font-800">{{ ranked.length }}</p><p class="text-sm text-slate-500">qualified entries</p></aside></div></section><section v-else class="panel p-8 text-center">Contest not found</section></div></template>
<script>
const{inject,computed,ref}=Vue;const{useRoute}=VueRouter;export default{setup(){const store=inject('store'),route=useRoute(),job=computed(()=>store.job(route.params.id)),contest=computed(()=>store.state.contests.find(item=>item.id===job.value?.contestId)),ranked=computed(()=>(contest.value?.bids||[]).slice().sort((a,b)=>a.amount-b.amount)),owner=computed(()=>job.value?.clientId===store.currentUser.value.id&&(store.isBuyer.value||store.isAdmin.value)),freelancer=computed(()=>store.isSupplier.value),ownBid=computed(()=>contest.value?.bids.find(item=>item.userId===store.currentUser.value.id)),amount=ref(0);function enter(){const value=Number(amount.value);if(!freelancer.value||ownBid.value||contest.value?.status!=='ACTIVE'||!Number.isFinite(value)||value<=0||value>job.value.budget)return store.notice('Contest entry is not valid','fa-shield-halved');contest.value.bids.push({userId:store.currentUser.value.id,amount:value});store.notice('Contest entry submitted')}function award(bid){if(!owner.value||contest.value?.winnerId||!contest.value?.bids.includes(bid))return store.notice('Award action denied','fa-shield-halved');contest.value.winnerId=bid.userId;contest.value.status='FINISHED';job.value.status='IN_PROGRESS';store.addNotification({userId:bid.userId,title:'You won the contest',text:job.value.title,link:`/project/${job.value.id}`,icon:'fa-trophy'});store.notice('Winner awarded')}return{store,job,contest,ranked,owner,freelancer,ownBid,amount,enter,award}}};
</script>
